import cv2, numpy as np
im=cv2.imread('first_frame.png')[:,:,::-1]
# per row/col ball crop threshold to inspect centroid and radial edges
for name,(x0,y0,x1,y1) in {'ball':(320,70,520,270),'block':(1010,130,1160,350)}.items():
 a=im[y0:y1,x0:x1].astype(float);r,g,b=a[...,0],a[...,1],a[...,2]
 if name=='ball': m=(r>g*1.08)&(r>b*1.25)&(r>20)&(g>12)
 else:m=(r>g*1.5)&(r>b*1.7)&(r>50)
 ys,xs=np.where(m)
 print(name,'centroid',x0+xs.mean(),y0+ys.mean(),'bbox',x0+xs.min(),y0+ys.min(),x0+xs.max(),y0+ys.max())
 if name=='ball':
  for yy in range(0,200,10):
   xx=np.where(m[yy])[0]
   if len(xx): print(y0+yy,x0+xx.min(),x0+xx.max(),len(xx))
PY"

